export const seismicStages=[['collection','Source collection','Retain original survey and supporting files'],['seismic','Seismic interpretation','Review surveys, horizons and faults'],['reports','Reports','Assemble reviewed evidence']];
export function workflows(project){return project?.workflows||['petrophysics'];}
export function allowedTool(id,project,modules){
  const selected=workflows(project),petro=selected.includes('petrophysics'),seismic=selected.includes('seismic');
  if(['home','projects','overview','data','collection','files','documents','map','reports','reviews','settings','catalog'].includes(id))return true;
  if(id==='rockphysics')return petro&&seismic;
  if(id==='seismic')return seismic;
  if(['interpretation','models','decisions'].includes(id))return petro||seismic;
  return petro;
}
export function overviewView({project,workspace,stages,esc,icon}){
  const files=workspace.files||[],activity=workspace.audit||[];
  return `<section class="project-focus"><div class="overview-heading"><div><div class="study-kicker">PROJECT OVERVIEW</div><h1>${esc(project.name)}</h1><p>${esc(project.description||'Your evidence, location and next steps.')}</p><div class="overview-tags">${workflows(project).map(w=>`<span>${w==='seismic'?'Seismic interpretation':'Petrophysics'}</span>`).join('')}<span>${project.storage==='cloud'?'Cloud':project.storage==='local'?'Local folder':project.storage==='legacy'?'Recovery draft':'Portable file'}</span></div></div><div class="actions"><button data-action="project-settings">${icon('settings')}Project settings</button><button class="primary" data-action="upload">${icon('upload')}Import sources</button></div></div><div class="evidence-strip">${[['Source files',files.length],['Registered wells',(workspace.wellDrafts||[]).length],['Saved configurations',Object.keys(workspace.configs||{}).length]].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="overview-columns"><section class="panel"><header class="panel-head"><h2>Your workflow</h2><small>Project tracking · not scientific approval</small></header><div class="workflow">${stages.map(([key,title,description],i)=>{const manual=project.stageStates?.[key];const status=manual?manual+' · user reported':key==='collection'&&files.length?'Sources stored':'Not started';return `<button class="overview-step" data-go="${key}"><span class="step-num">${i+1}</span><span><strong>${esc(title)}</strong><small>${esc(description)}</small></span><span class="workflow-status">${esc(status)}</span>${icon('arrow')}</button>`;}).join('')}</div>${!files.length?'<div class="overview-next"><h3>Begin with your source evidence</h3><p>Import original files to your chosen storage. Parsing and scientific calculations will be available in a later phase.</p></div>':''}</section><div><section class="panel"><header class="panel-head"><h2>Study location</h2><button data-go="map">Open map ${icon('arrow')}</button></header>${project.coordinates?'<div id="overview-map" class="real-map"></div>':'<div class="location-empty">'+icon('pin')+'<h3>Add your study location</h3><p>Set a site position to place this project on the map.</p><button data-action="project-settings">Add location</button></div>'}<div class="location-summary"><strong>${esc(project.location||'Location not specified')}</strong>${project.coordinates?`<span>${project.coordinates.lat}, ${project.coordinates.lng} · WGS84</span>`:''}</div></section><section class="panel"><header class="panel-head"><h2>Recent activity</h2></header><div class="panel-body">${activity.length?activity.slice(0,5).map(entry=>`<div class="activity"><span>${icon('clock')}</span><div><p>${esc(entry.action)}</p><small>${esc(new Date(entry.time).toLocaleString())}</small></div></div>`).join(''):'<p class="sub">Your saved project actions will appear here.</p>'}</div></section></div></div></section>`;
}
export function switcherView(project,esc,icon){return `<div class="project-picker"><button id="project-picker-trigger" aria-expanded="false" aria-controls="project-picker-menu">${icon('layers')}<span>${esc(project?.name||'Select project')}</span>${icon('down')}</button><div id="project-picker-menu" hidden><label class="field"><span>Switch project</span><input id="project-picker-search" placeholder="Find a project…" autocomplete="off"></label><div id="project-picker-results"></div><button id="picker-all-projects">${icon('layers')}All projects</button></div></div>`;}
export function bindSwitcher({portfolio,openProject,navigate,esc,icon}){
  const trigger=document.querySelector('#project-picker-trigger'),menu=document.querySelector('#project-picker-menu');if(!trigger)return;
  const close=()=>{menu.hidden=true;trigger.setAttribute('aria-expanded','false');};
  const populate=()=>{const q=document.querySelector('#project-picker-search').value.toLowerCase();const target=document.querySelector('#project-picker-results');target.innerHTML=portfolio.records.filter(p=>p.status!=='Trash'&&p.name.toLowerCase().includes(q)).map(p=>`<button data-pick-project="${p.id}"><span><strong>${esc(p.name)}</strong><small>${p.storage==='cloud'?'Cloud':p.storage==='local'?'Local folder':p.storage==='legacy'?'Recovery draft':'Portable file'}${p.status==='Archived'?' · Archived':''}</small></span>${p.id===portfolio.activeId?icon('check'):''}</button>`).join('')||'<p class="sub">No matching projects.</p>';target.querySelectorAll('button').forEach(b=>b.onclick=()=>{close();openProject(b.dataset.pickProject);});};
  trigger.onclick=()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden){populate();document.querySelector('#project-picker-search').focus();}};
  document.querySelector('#project-picker-search').oninput=populate;
  document.querySelector('#picker-all-projects').onclick=()=>{close();navigate('projects');};
  menu.onkeydown=event=>{const buttons=[...menu.querySelectorAll('input,button')];let index=buttons.indexOf(document.activeElement);if(event.key==='Escape'){event.preventDefault();close();trigger.focus();}if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[index].focus();}};
  document.addEventListener('click',event=>{if(!event.target.closest('.project-picker'))close();},{signal:pickerSignal()});
}
let previous;
function pickerSignal(){previous?.abort();previous=new AbortController();return previous.signal;}
